#include "ducklips/continuous_glottis.hpp"
#include <cstdio>
#include <algorithm>
#include <cmath>
#include <string>
#include <stdexcept>
int main(int argc,char** argv){try{
 const bool lower=argc<2 || std::string(argv[1])=="lower";const int steps=argc>2?std::stoi(argv[2]):2000;const double duration=argc>3?std::stod(argv[3]):.0002;const bool linear=argc>4 && std::string(argv[4])=="linear";const bool dissipative=argc>5 && std::string(argv[5])=="dissipative";ducklips::FoldParameters f;ducklips::FoldState initial;initial.rest_area=3e-6;
 (lower?initial.lower_position:initial.upper_position)={-2.9e-6/(2*f.length),-2.9e-6/(2*f.length)};(lower?initial.lower_velocity:initial.upper_velocity)={-.05,-.05};
 ducklips::ContinuousGlottis source;if(!source.prepare(f,{},1.,initial,{}, {},1.,linear?ducklips::ContourPressureProfile::linear_span:ducklips::ContourPressureProfile::flat_caps)){throw std::runtime_error("prepare");}ducklips::ContinuousGlottalState start,state;if(!source.state(start)){throw std::runtime_error("state");}double loss=0,numerical=0,physical=0,net=0,min_area=1.,maximum_balance=0;int closes=0,opens=0;double first_close=-1,first_open=-1;bool was_open=true;const double dt=duration/steps;
 for(int n=0;n<=steps;++n){if(!source.state(state)){throw std::runtime_error("state");}min_area=std::min(min_area,state.area[lower?0:1]);maximum_balance=std::max(maximum_balance,std::abs(state.energy-start.energy+loss));const bool open=state.area[lower?0:1]>0;if(was_open && !open){++closes;if(first_close<0){first_close=n*dt;}}if(!was_open && open){++opens;if(first_open<0){first_open=n*dt;}}was_open=open;if(n%10==0 || n==steps){std::printf("{\"step\":%d,\"time\":%.17g,\"area\":[%.17g,%.17g],\"effort\":[%.17g,%.17g],\"flow\":[%.17g,%.17g,%.17g],\"area_rate\":[%.17g,%.17g],\"energy\":%.17g,\"loss\":%.17g,\"balance\":%.17g,\"mass_balance\":%.17g}\n",n,n*dt,state.area[0],state.area[1],state.effort[0],state.effort[1],state.flow[0],state.flow[1],state.flow[2],f.length*(state.folds.lower_velocity[0]+state.folds.lower_velocity[1]),f.length*(state.folds.upper_velocity[0]+state.folds.upper_velocity[1]),state.energy,loss,state.energy-start.energy+loss,state.mass[0]+state.mass[1]-start.mass[0]-start.mass[1]-net);std::fflush(stdout);}if(n==steps){std::fprintf(stderr,"{\"closures\":%d,\"reopenings\":%d,\"first_closed_s\":%.17g,\"first_reopened_s\":%.17g,\"minimum_area\":%.17g,\"physical_loss_J\":%.17g,\"numerical_loss_J\":%.17g,\"maximum_balance_J\":%.17g}\n",closes,opens,first_close,first_open,min_area,physical,numerical,maximum_balance);return 0;}
 if(!source.advance(dt,0.,0.,0.,{},dissipative?ducklips::ContinuousGlottalUpdate::dissipative:ducklips::ContinuousGlottalUpdate::symmetric)){std::fprintf(stderr,"advance failed %d dt %.17g area %.17g %.17g velocity %.17g %.17g\n",n,dt,state.area[0],state.area[1],f.length*(state.folds.lower_velocity[0]+state.folds.lower_velocity[1]),f.length*(state.folds.upper_velocity[0]+state.folds.upper_velocity[1]));return 2;}numerical+=source.last.numerical_loss;physical+=source.last.fluid_loss+source.last.tissue_loss+source.last.load_work;loss+=source.last.numerical_loss+source.last.fluid_loss+source.last.tissue_loss+source.last.load_work;net+=dt*(source.last.flow[0]-source.last.flow[2]);
 }
}catch(const std::exception& e){std::fprintf(stderr,"%s\n",e.what());return 1;}}
